"""Миграции и модели не расходятся.

Цикл upgrade → downgrade → upgrade выполняется в conftest на каждый прогон; здесь —
проверка, что после upgrade head autogenerate не находит отличий от моделей.
Ловит «поменял модель, забыл миграцию».
"""

import asyncio

from alembic import command
from alembic.config import Config


async def test_models_match_migrations() -> None:
    # command.check бросает AutogenerateDiffsDetected, если есть расхождения.
    await asyncio.to_thread(command.check, Config("alembic.ini"))
